"""The storage seam: a backend-agnostic.

Holds embedded chunk records and answers vector/hybrid queries with optional
metadata filtering. Abstracting this lets the vector DB be swapped
without touching chunking, embedding, sync, or the retriever
— the caller embeds; the store only stores and searches.
"""

from abc import ABC, abstractmethod
from typing import Any, Dict, List, Optional

import numpy as np
from pydantic import BaseModel

from rasa.builder.document_retrieval.local.chunking import Chunk


class StoreHit(BaseModel):
    """A single search hit returned by the vector store."""

    chunk: Chunk
    score: Optional[float] = None


class BaseVectorStore(ABC):
    """Stores embedded chunk records and answers similarity queries."""

    @abstractmethod
    def exists(self) -> bool:
        """Whether the underlying table/collection has been created yet."""

    @abstractmethod
    def add(self, records: List[Dict[str, Any]]) -> None:
        """Append chunk records (each carrying a ``vector`` plus metadata)."""

    @abstractmethod
    def drop(self) -> None:
        """Drop the entire table/collection (no-op if it does not exist)."""

    @abstractmethod
    def ensure_text_index(self) -> None:
        """(Re)build the full-text index that backs hybrid search."""

    @abstractmethod
    def search(
        self,
        *,
        query_vector: np.ndarray,
        query_text: Optional[str] = None,
        top_k: int,
        hybrid: bool = False,
        where: Optional[str] = None,
    ) -> List[StoreHit]:
        """Return the top-k hits for a query vector (optionally hybrid + filtered)."""
